【整段代码·ECharts】编写一个完整的 ECharts 散点图，要求：①使用 dataset 组件管理数据；②X 轴为「身高」，Y 轴为「体重」；③通过 encode 进行数据映射；④根据第三个维度「年龄」使用 visualMap 对颜色进行连续映射。
📄 代码：
var myChart = echarts.init(document.getElementById('main'));
var option = {
    title: { text: '身高体重年龄散点图' },
    dataset: {
        dimensions: ['身高(cm)', '体重(kg)', '年龄'],
        source: [
            [165, 55, 22], [172, 68, 28], [158, 50, 25],
            [180, 80, 35], [168, 62, 30], [175, 72, 27],
            [162, 53, 21], [170, 65, 33], [178, 75, 40],
            [160, 48, 19]
        ]
    },
    xAxis: { name: '身高(cm)', type: 'value' },
    yAxis: { name: '体重(kg)', type: 'value' },
    visualMap: {
        type: 'continuous',
        dimension: 2,
        min: 18, max: 45,
        inRange: { color: ['#50A3BA', '#EAC736', '#D94E5D'] },
        text: ['高年龄', '低年龄']
    },
    series: [{
        type: 'scatter',
        encode: { x: '身高(cm)', y: '体重(kg)' },
        symbolSize: 12
    }],
    tooltip: { trigger: 'item' }
};
myChart.setOption(option);

