【整段代码·ECharts】编写一个完整的 ECharts 仪表盘（gauge）图表，要求：①显示完成率百分比；②设置不同区间颜色（绿/黄/红）；③指针指向当前数值 73.5%；④显示标题和数值标签。
📄 代码：
var myChart = echarts.init(document.getElementById('main'));
var option = {
    title: { text: '年度目标完成率', left: 'center', top: 20 },
    series: [{
        type: 'gauge',
        startAngle: 210,
        endAngle: -30,
        center: ['50%', '55%'],
        radius: '85%',
        min: 0,
        max: 100,
        splitNumber: 10,
        axisLine: {
            lineStyle: {
                width: 20,
                color: [
                    [0.3, '#67C23A'],   // 0-30% 绿色
                    [0.7, '#E6A23C'],   // 30-70% 黄色
                    [1.0, '#F56C6C']    // 70-100% 红色
                ]
            }
        },
        pointer: {
            length: '70%',
            width: 6,
            itemStyle: { color: '#303133' }
        },
        axisTick: { distance: -20, length: 8 },
        splitLine: { distance: -26, length: 16 },
        axisLabel: { distance: 35, fontSize: 12 },
        detail: {
            valueAnimation: true,
            formatter: '{value}%',
            fontSize: 28,
            fontWeight: 'bold',
            offsetCenter: [0, '80%']
        },
        data: [{ value: 73.5, name: '完成率' }]
    }]
};
myChart.setOption(option);
